B.an=s([],t.zr)
B.WX=s(["Th..Thank you, Mateo. I..I owe you my life...","The words grow distant as exhaustion pulls you back into darkness."],t.s)
B.Ol=new A.cw("Close your eyes","intro_pass_out_to_spanish_home",!0,!1)
