B.Xu=s(["Then what should I call you?"],t.s)
B.Og=new A.cw("Choose your name","intro_choose_player_name",!0,!1)
B.UT=s([B.Og],t.u)
B.P3=new A.cj(B.an,B.Xu,null,null,null,B.UT)
